(function(){ if (document.getElementById("dpCss")) return; const s = document.createElement("style"); s.id = "dpCss"; s.textContent = CSS; (document.head || document.documentElement).append(s); })();
// 2026-11-09 再改（样板 样板/越聊越深多过脑子样板.html，用户：「过脑子的太少，展示给用户的东西太少」「听一听的游戏反倒更好」「可以，照这个改」）
