const FLD = ["l1", "l2", "l3", "l4"];
const sealed = (s, n) => !!(s[FLD[n]] && s[FLD[n]].d);
const shuf = (a, seed) => a.map((x, i) => [((i + 3) * 7919 * (seed || 7)) % 101, x]).sort((p, q) => p[0] - q[0]).map(x => x[1]);
const sayS = t => { try { speechSynthesis.cancel(); if (AU){ AU.pause(); AU = null; } const u = new SpeechSynthesisUtterance(t); u.lang = "en-GB"; u.rate = .68; speechSynthesis.speak(u); } catch(e){} };
const sents = t => String(t || "").split(/(?<=[.!?。！？])\s*/).map(x => x.trim()).filter(Boolean);
// 这个话题的词（岛上现成的 8 个，带别的说法）
const TW = () => { try { const X = window.HVI && window.HVI.tkChatOf(isle, tk); return (X && X.words) || []; } catch(e){ return []; } };
const wre = w => new RegExp("\\b(" + [w.en].concat(w.alt || []).map(x => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|") + ")\\b", "i");
