    ws.forEach((w, i) => { cc.push(w); const left = ws.length - i - 1; if ((cc.length >= sz && !STOP.has(w.toLowerCase().replace(/[^a-z']/g, "")) && left >= 2) || !left){ chunks.push(cc.join(" ")); cc = []; } }); if (cc.length) chunks.push(cc.join(" "));
