    '<div class="mbt"><button class="pill lt" id="wbZm">🎤 用中文说</button><button class="pill say" id="wbZgo">变成英文 →</button></div><div class="live" id="wbZl"></div><div class="res" id="wbZr"></div></div>';
  $("#wbZm").onclick = () => listen($("#wbZl"), t => { if (t) $("#wbZ").value = ($("#wbZ").value + " " + t).trim(); $("#wbZl").textContent = ""; }, "zh-CN");
