    const sys = q.pro ? `You help a Chinese-speaking software developer (English around B1) say something at work in natural, professional but friendly spoken English. Situation: ${q.pro.title[1]} — ${q.pro.task}. Keep their real details.` : `You help a Chinese-speaking English learner (around B1) answer a casual question in natural, spoken English. Question: "${plain(q.q[0])}". Turn what they say (in Chinese) into 1–3 short, natural spoken English sentences in the first person, keeping their meaning and their real details, no fancy words. Mark 2–4 reusable chunks (natural multi-word phrases) with [square brackets]. Reply ONLY JSON: {"lines":[{"en":"...","zh":"..."}]}`;
    let j = null; try { j = await ai.json([{role: "user", content: zh}], {modelTier: "chat", system: sys, cache: false}); } catch(e){ j = null; }
